var pool = ArrayPool<byte>.Shared;
byte[] buffer = pool.Rent(90_000);
try
{
    int written = ReadCsvRow(buffer);
    ProcessRow(buffer.AsSpan(0, written));
}
finally
{
    pool.Return(buffer, clearArray: true);
}

